class TestPropertyBased:
    """Invariant testing with Hypothesis."""

    @given(st.text(min_size=0, max_size=500))
    @settings(max_examples=50, suppress_health_check=[HealthCheck.too_slow])
    def test_verify_never_crashes_on_arbitrary_text(self, cov_instance, text):
        """Verify must never crash on arbitrary text input."""
        try:
            result = cov_instance.verify(text)
            assert isinstance(result, VerificationResult)
            assert 0.0 <= result.confidence <= 1.0
        except (ValueError, TypeError) as e:
            # Acceptable if the implementation validates input strictly
            pytest.skip(f"Input rejected by design: {e}")

    @given(st.lists(st.text(min_size=1, max_size=100), min_size=0, max_size=20))
    @settings(max_examples=50, suppress_health_check=[HealthCheck.too_slow])
    def test_verify_never_crashes_on_step_lists(self, verification_engine, texts):
        """Verify must handle arbitrary step lists."""
        chain = [
            ReasoningStep(id=f"s{i}", text=t, step_type="premise")
            for i, t in enumerate(texts)
        ]
        try:
            result = verification_engine.verify(chain)
            assert isinstance(result, VerificationResult)
        except (ValueError, TypeError) as e:
            pytest.skip(f"Input rejected by design: {e}")

    @given(st.floats(min_value=0.0, max_value=1.0))
    @settings(max_examples=20)
    def test_confidence_values_are_valid(self, confidence):
        """Confidence values must be within [0, 1]."""
        step = ReasoningStep(id="s1", text="Test", confidence=confidence)
        assert 0.0 <= step.confidence <= 1.0

    @given(st.text(min_size=0, max_size=100))
    @settings(max_examples=20)
    def test_detector_returns_list(self, detector_instance, text):
        """Detector must always return a list."""
        result = detector_instance.detect(text)
        assert isinstance(result, list)

    @given(st.text(min_size=0, max_size=100))
    @settings(max_examples=20)
    def test_extractor_returns_list(self, extractor_instance, text):
        """Extractor must always return a list."""
        result = extractor_instance.extract(text)
        assert isinstance(result, list)


