class TestPerformanceSmoke:
    """Performance sanity checks to catch severe regressions."""

    def test_verify_latency_smoke(self, cov_instance):
        """Verification should complete within reasonable time."""
        text = _valid_reasoning_text() * 10  # ~10x normal size
        start = time.time()
        cov_instance.verify(text)
        elapsed = time.time() - start
        assert elapsed < 2.0, f"Verification took {elapsed:.2f}s, expected < 2.0s"

    def test_detector_latency_smoke(self, detector_instance):
        """Detection should complete within reasonable time."""
        text = _invalid_reasoning_text() * 50
        start = time.time()
        detector_instance.detect(text)
        elapsed = time.time() - start
        assert elapsed < 2.0, f"Detection took {elapsed:.2f}s, expected < 2.0s"

    def test_extractor_latency_smoke(self, extractor_instance):
        """Extraction should complete within reasonable time."""
        text = _valid_reasoning_text() * 50
        start = time.time()
        extractor_instance.extract(text)
        elapsed = time.time() - start
        assert elapsed < 2.0, f"Extraction took {elapsed:.2f}s, expected < 2.0s"

    def test_repeated_verification_stability(self, cov_instance):
        """Repeated verification should not degrade performance."""
        text = _valid_reasoning_text()
        # Warm-up
        cov_instance.verify(text)
        # Timed runs
        times = []
        for _ in range(5):
            start = time.time()
            cov_instance.verify(text)
            times.append(time.time() - start)
        avg_time = sum(times) / len(times)
        assert avg_time < 1.0, f"Average verification time {avg_time:.2f}s, expected < 1.0s"


